import{At as e,Pt as t,Ut as n,gt as r,ht as i,mt as a,n as o,pt as s,ut as c}from"./chunks/framework.BrKcMR_c.js";var l=JSON.parse(`{"title":"Permission reference","description":"","frontmatter":{},"headers":[],"relativePath":"reference/PERMISSIONS.md","filePath":"reference/PERMISSIONS.md","lastUpdated":1789092097000}`),u={name:`reference/PERMISSIONS.md`};function d(o,l,u,d,f,p){let m=t(`Term`);return e(),s(`div`,null,[l[14]||=c(`h1`,{id:`permission-reference`,tabindex:`-1`},[i(`Permission reference `),c(`a`,{class:`header-anchor`,href:`#permission-reference`,"aria-label":`Permalink to “Permission reference”`},`​`)],-1),c(`p`,null,[r(m,{term:`kid`},{default:n(()=>[...l[0]||=[i(`Kid`,-1)]]),_:1}),l[3]||=i(` separates native file authority, native command authority, external `,-1),r(m,{term:`mcp`},{default:n(()=>[...l[1]||=[i(`MCP`,-1)]]),_:1}),l[4]||=i(` tool approval and `,-1),r(m,{term:`judas`},{default:n(()=>[...l[2]||=[i(`JUDAS`,-1)]]),_:1}),l[5]||=i(` connection policy. Models, skills, memory and tool results do not administer these controls.`,-1)]),l[15]||=a(`<h2 id="native-herder-file-tools" tabindex="-1">Native Herder file tools <a class="header-anchor" href="#native-herder-file-tools" aria-label="Permalink to “Native Herder file tools”">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>Behavior</th></tr></thead><tbody><tr><td><code>pen_list_files</code></td><td>Sorted, workspace-relative listing with bounded pages and <code>next_after</code>.</td></tr><tr><td><code>pen_read_file</code></td><td>Bounded text read with <code>next_start_line</code> for continuation.</td></tr><tr><td><code>pen_search</code></td><td>Literal-text search in eligible source files.</td></tr><tr><td><code>pen_write_file</code></td><td>Create a new file; an existing path is an error.</td></tr><tr><td><code>pen_edit_file</code></td><td>Replace one exact unique fragment from the current file.</td></tr></tbody></table>`,2),c(`p`,null,[r(m,{term:`herder`},{default:n(()=>[...l[6]||=[i(`Herder`,-1)]]),_:1}),l[10]||=i(` is available for a turn in a configured `,-1),r(m,{term:`pen`},{default:n(()=>[...l[7]||=[i(`Pen`,-1)]]),_:1}),l[11]||=i(` workspace when chat `,-1),r(m,{term:`tool`},{default:n(()=>[...l[8]||=[i(`tools`,-1)]]),_:1}),l[12]||=i(` and the relevant `,-1),r(m,{term:`goated`},{default:n(()=>[...l[9]||=[i(`extension`,-1)]]),_:1}),l[13]||=i(` operations are enabled. Native reads are bounded; creation and editing require host approval or a matching remembered grant.`,-1)]),l[16]||=a(`<table tabindex="0"><thead><tr><th>Grant</th><th>Lifetime and effect</th></tr></thead><tbody><tr><td>Allow Once</td><td>The prepared action shown in the dialog.</td></tr><tr><td>Allow for this chat</td><td>Native creation/editing in that chat, including after reopening it.</td></tr><tr><td>Always allow for this Pen</td><td>Native creation/editing for current and future chats in the Pen.</td></tr><tr><td>Ask for approval</td><td>Require approval after removing authority applicable to the selected scope.</td></tr></tbody></table><p>A Pen-wide grant is broader than a chat grant. Selecting a narrower composer option while one is active can affect other chats, as the UI explains. Resetting file permissions from the Pen page clears all file grants in the Pen. Moving a chat clears its chat-only grant; changing the workspace clears file grants for the Pen.</p><p>Every write rechecks the prepared action, workspace and filesystem state. UTF-8 files are limited to 1 MiB. Reads return at most 200 lines and 32 KiB; directory pages at most 200 entries. Symbolic links, multiply linked files and <code>.git</code> metadata are excluded. Tool-call arguments are capped at 64 KiB by GOATed. An identical edit replacement reports No change; an intervening file change invalidates a prepared edit.</p><h2 id="native-command-jobs" tabindex="-1">Native command jobs <a class="header-anchor" href="#native-command-jobs" aria-label="Permalink to “Native command jobs”">​</a></h2><p><code>pen_run_command</code> starts a permitted executable with literal <code>args</code>. <code>pen_command_status</code> reads the job identified by its exact returned ID; <code>pen_stop_command</code> stops that job. Stop is not file deletion. Shell substitutions, redirection and <code>~</code> are not expanded in literal argument fields.</p><p>A command whitelist entry authorises an executable for one chat or all Pen chats, within its filesystem and network limits. It permits any arguments and child commands inside those boundaries, not only the command line first shown. The owner can resolve and edit entries without running the program. Basic offline inspection commands are allowed; other executables require approval. Native file grants do not grant command authority.</p><p>Networking is blocked by default. A call must request it, its executable grant must permit it, and JUDAS must admit it. A network-enabled grant also permits offline invocations. Pen-wide grants are additive; a narrower chat entry does not revoke them.</p><p>Command networking is intentionally coarser than HTTP endpoint policy. <strong>Local networks only</strong> cannot enforce a LAN-only boundary on arbitrary child-process traffic, so network-enabled jobs require Configured connections. Offline confined jobs can remain available in restricted modes. Revocation and turn completion stop remaining registered command work; completed filesystem or remote effects are not rolled back.</p><p>Jobs use a confined working directory, isolated home/cache and read-only system/toolchain access. They are non-interactive, have bounded output and a maximum ten-minute deadline. The initial Herder default timeout is 120 seconds. Detached background services are unsupported. The model must inspect required job completion before declaring success.</p><p>Confinement currently depends on macOS <code>sandbox-exec</code>. Missing runtimes, authenticated registries and host configuration require deliberate compatibility work, not automatic access to personal files. An approved shell command can modify files even when Herder’s separate native-write option is off.</p><h2 id="external-mcp-and-failure-boundaries" tabindex="-1">External MCP and failure boundaries <a class="header-anchor" href="#external-mcp-and-failure-boundaries" aria-label="Permalink to “External MCP and failure boundaries”">​</a></h2><p>MCP calls use configured server/tool authority and separate approvals. Remembered approval is checked against configuration identity. GOAT’s native whitelist does not configure an external shell server. Restricted JUDAS modes block external MCP processes because their own network behavior is not confined by GOAT’s HTTP policy.</p><p>A timeout or missing saved result can leave an unknown outcome. Inspect affected state before retrying. GOAT never executes tool markup printed as text and does not grant additional authority to recover from a failure.</p><p>See <a href="/how-to/PERMISSIONS">Manage permissions</a>, <a href="/how-to/WORK-ON-CODE">Work on code</a> and <a href="/reference/CONNECTIONS">Connection policy</a>.</p>`,14)])}var f=o(u,[[`render`,d]]);export{l as __pageData,f as default};